var doc = app.activeDocument;
var cfg = new RadialRepeatConfig();
cfg.numberOfInstances = 12;
cfg.radius = 150;
var rr = doc.radialRepeatItems.add(doc.selection[0], cfg);

var r = app.activeDocument.rasterItems;
for (var i = 0; i < r.length; i++) {
  $.writeln(r[i].name + " " + r[i].imageColorSpace + " " + r[i].bitsPerChannel);
}

var doc = app.activeDocument;
var s = doc.spots.add();
s.name = "Brand Red";
var c = new CMYKColor(); c.cyan = 0; c.magenta = 100; c.yellow = 90; c.black = 0;
s.color = c;
s.colorType = ColorModel.SPOT;

var st = app.activeDocument.stories;
for (var i = 0; i < st.length; i++) {
  $.writeln(st[i].textFrames.length + " frames: " + st[i].textRange.contents);
}

var doc = app.activeDocument;
var sw = doc.swatches.add();
sw.name = "Sky";
var c = new RGBColor(); c.red = 40; c.green = 150; c.blue = 230;
sw.color = c;
doc.selection[0].fillColor = sw.color;

var doc = app.activeDocument;
var g = doc.swatchGroups.add();
g.name = "Brand";
g.addSwatch(doc.swatches.getByName("Sky"));

var doc = app.activeDocument;
var sym = doc.symbols.getByName("Star");
for (var i = 0; i < 5; i++) {
  var it = doc.symbolItems.add(sym);
  it.position = [i * 60, -100];
}

var doc = app.activeDocument;
var sym = doc.symbols.add(doc.selection[0], SymbolRegistrationPoint.SYMBOLCENTERPOINT);
sym.name = "Star";
var inst = doc.symbolItems.add(sym);

var doc = app.activeDocument;
var cfg = new SymmetryRepeatConfig();
cfg.axisRotationAngleInRadians = 0; // horizontal axis; default 1.57 is vertical
var m = doc.symmetryRepeatItems.add(doc.selection[0], cfg);

var it = app.activeDocument.selection[0];
var t = it.tags.add();
t.name = "sku";
t.value = "A-1042";
var back = it.tags.getByName("sku").value;

var name = "MyriadPro-Bold";
if (app.textFonts.isFontAvailable(name)) {
  var f = app.textFonts.getByName(name);
  app.activeDocument.textFrames[0].textRange.characterAttributes.textFont = f;
}

var doc = app.activeDocument;
var t = doc.textFrames.pointText([100, -100]);
t.contents = "SALE 50%";
var box = doc.pathItems.rectangle(-200, 100, 300, 120);
var area = doc.textFrames.areaText(box);
area.contents = "Body copy flows inside the box.";

var runs = app.activeDocument.textFrames[0].textRanges;
for (var i = 0; i < runs.length; i++) {
  $.writeln(runs[i].contents + " / " + runs[i].characterAttributes.size);
}

var doc = app.activeDocument;
var v = doc.variables.add();
v.kind = VariableKind.TEXTUAL;
v.name = "headline";
doc.textFrames[0].contentVariable = v;

var vs = app.activeDocument.views;
for (var i = 0; i < vs.length; i++) {
  vs[i].zoom = 1;
}
app.redraw();

var red = new RGBColor(); red.red = 230;
var w = app.activeDocument.textFrames[0].words;
for (var i = 0; i < w.length; i++) {
  if (w[i].contents == "FREE") w[i].characterAttributes.fillColor = red;
}

var c = new CMYKColor();
c.cyan = 0; c.magenta = 100; c.yellow = 100; c.black = 0;
var p = app.activeDocument.pathItems.rectangle(0, 0, 200, 100);
p.fillColor = c;

var col = app.activeDocument.selection[0].fillColor;
if (col.typename == "CMYKColor") $.writeln(col.cyan + "/" + col.magenta + "/" + col.yellow + "/" + col.black);
else if (col.typename == "RGBColor") $.writeln(col.red + "," + col.green + "," + col.blue);
else if (col.typename == "SpotColor") $.writeln(col.spot.name + " @ " + col.tint + "%");

var doc = app.activeDocument;
var g = doc.gradients.add();
g.type = GradientType.RADIAL;
var gc = new GradientColor();
gc.gradient = g;
doc.selection[0].fillColor = gc;

var g = new GrayColor();
g.gray = 40;
app.activeDocument.selection[0].strokeColor = g;

var lab = new LabColor();
lab.l = 48; lab.a = 68; lab.b = 47;
var s = app.activeDocument.spots.add();
s.name = "Measured Red";
s.color = lab;
s.colorType = ColorModel.SPOT;

var p = app.activeDocument.selection[0];
p.fillColor = new NoColor();
var k = new GrayColor(); k.gray = 100;
p.strokeColor = k;
p.strokeWidth = 1;

var pats = app.activeDocument.patterns;
for (var i = 0; i < pats.length; i++) {
  $.writeln(pats[i].name);
}

var doc = app.activeDocument;
var pc = new PatternColor();
pc.pattern = doc.patterns.getByName("Grid");
var p = doc.selection[0];
p.fillColor = pc;
p.resize(50, 50, false, true, false);

var hex = "1E90FF";
var c = new RGBColor();
c.red = parseInt(hex.substr(0, 2), 16); c.green = parseInt(hex.substr(2, 2), 16); c.blue = parseInt(hex.substr(4, 2), 16);
app.activeDocument.selection[0].fillColor = c;

var s = app.activeDocument.spots.getByName("Brand Red");
var sc = new SpotColor();
sc.spot = s;
sc.tint = 60;
app.activeDocument.selection[0].fillColor = sc;

var doc = app.activeDocument;
var sc = new SpotColor();
sc.spot = doc.spots.getByName("PANTONE 186 C");
sc.tint = 100;
doc.selection[0].fillColor = sc;

var doc = app.activeDocument;
var sw = doc.swatches.getByName("Sky");
for (var i = 0; i < doc.selection.length; i++) {
  doc.selection[i].fillColor = sw.color;
}

var g = app.activeDocument.swatchGroups.getByName("Brand");
var list = g.getAllSwatches();
for (var i = 0; i < list.length; i++) {
  $.writeln(list[i].name);
}

var doc = app.activeDocument;
doc.importVariables(File("C:/data/cards.xml"));
for (var i = 0; i < doc.dataSets.length; i++) {
  doc.dataSets[i].display();
  doc.exportFile(File("C:/out/card_" + i + ".png"), ExportType.PNG24);
}

var vars = app.activeDocument.variables;
for (var i = 0; i < vars.length; i++) {
  $.writeln(vars[i].name + " " + vars[i].kind + " bound to " + vars[i].pageItems.length);
}

var doc = app.activeDocument;
var what = new ExportForScreensItemToExport();
what.artboards = "1-2";
var opt = new ExportForScreensOptionsPNG24();
opt.scaleTypeValue = 2;
doc.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_PNG24, opt, what, "hero_");

var o = new ExportForScreensOptionsAVIF();
o.losslessCompression = false;
o.imageQuality = 45;
o.scaleTypeValue = 2;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_AVIF, o);

var o = new ExportForScreensOptionsJPEG();
o.compressionMethod = JPEGCompressionMethodType.PROGRESSIVE;
o.scaleType = ExportForScreensScaleType.SCALEBYWIDTH;
o.scaleTypeValue = 1080;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_JPEG80, o);

var o = new ExportForScreensOptionsPNG24();
o.transparency = true;
o.scaleTypeValue = 3;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_PNG24, o);

var o = new ExportForScreensOptionsPNG8();
o.colorCount = 32;
var bg = new RGBColor(); bg.red = 255; bg.green = 255; bg.blue = 255;
o.matteColor = bg;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_PNG8, o);

var o = new ExportForScreensOptionsWebOptimizedSVG();
o.fontType = SVGFontType.OUTLINEFONT;
o.svgResponsive = false;
o.svgMinify = true;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_SVG, o);

var o = new ExportForScreensOptionsWebP();
o.losslessCompression = false;
o.imageQuality = 80;
o.scaleTypeValue = 2;
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_WEBP, o);

var o = new ExportForScreensPDFOptions();
o.pdfPreset = app.PDFPresetsList[0];
var what = new ExportForScreensItemToExport();
what.artboards = "all";
app.activeDocument.exportForScreens(Folder("C:/out"), ExportForScreensType.SE_PDF, o, what);

var o = new ExportOptionsAutoCAD();
o.exportFileFormat = AutoCADExportFileFormat.DXF;
o.unit = AutoCADUnit.Millimeters;
o.convertTextToOutlines = true;
app.activeDocument.exportFile(File("C:/out/dieline.dxf"), ExportType.AUTOCAD, o);
